/* Native extraction oracle. Real VM/read/map helpers; substituted output sink. */
#define LS_MAP_GLUE_IMPL 1
#include "ls_map_glue.h"
#include <assert.h>

struct event {
    uint32_t magic, abi;
    uint64_t run, sequence, lifetime, attempt, failures;
    uint32_t flags, path, total, reserved;
    unsigned char nonce[32];
};
static struct event last;
static unsigned emissions, reject_output;
static struct ubpf_vm *vm;
static ubpf_jit_ex_fn jit;
static const char nonce[] = "0123456789abcdef0123456789abcdef";
static const char request[] = "POST /mcp HTTP/1.1\r\nHost: fixture\r\n"
    "X-Proof-Nonce: 0123456789abcdef0123456789abcdef\r\n\r\nBODY";

int ls_tp_publish_raw(int slot, const void *data, unsigned long size)
{
    assert(slot == 8 && size == sizeof last && size == 96);
    memcpy(&last, data, size);
    assert(last.magic == 0x43414e44 && last.abi == 1);
    emissions++;
    return reject_output ? -1 : 0;
}

static void seed(uint64_t life, uint64_t attempt, uint64_t state)
{
    uint64_t key = 1, value[4] = {101, life, attempt, state};
    struct ls_map_set *set = ls_map_current();
    for (uint32_t i = 0; i < atomic_load(&g_ls_nshapes); i++) {
        if (!strcmp(g_ls_names[i], "life_objects")) {
            struct ls_map *map = ls_map_get(set, (set->generation << 8) | i);
            assert(map && !ls_map_update(map, (void *)&key, (void *)value));
            return;
        }
    }
    assert(0);
}

static void call(uint64_t address, const char *data, size_t len, int mode)
{
    uint64_t ctx[12] = {address, 1, (uintptr_t)data, len};
    uint64_t ret = 99;
    uint8_t stack[4096] = {0};
    emissions = 0;
    g_ls_cur_slot = 8;
    ls_config_begin(&g_ls_config_view, 8);
    if (mode)
        ret = jit(ctx, sizeof ctx, stack, sizeof stack);
    else
        assert(!ubpf_exec_ex(vm, ctx, sizeof ctx, &ret, stack, sizeof stack));
    g_ls_config_view.active = 0;
    g_ls_cur_slot = -1;
    assert(ret == 0 && emissions == 1);
    if (last.flags != 1) {
        unsigned char zero[32] = {0};
        assert(!last.path && !memcmp(last.nonce, zero, 32));
    }
}

int main(int argc, char **argv)
{
    assert(argc == 2);
    FILE *file = fopen(argv[1], "rb");
    assert(file && !fseek(file, 0, SEEK_END));
    long length = ftell(file);
    assert(length > 0 && !fseek(file, 0, SEEK_SET));
    void *object = malloc((size_t)length);
    assert(object && fread(object, 1, (size_t)length, file) == (size_t)length);
    fclose(file);
    g_ls_config.session = 42;
    for (int mode = 0; mode < 2; mode++) {
        assert(!ls_map_reset_shapes());
        struct ls_config_request r = {0};
        r.abi = r.schema = r.entries = 1;
        r.session = 42;
        r.instance = ls_config_new_instance(&g_ls_config, 8);
        memset(r.program_sha256, 0xab, 32);
        g_ls_config.loading = r.instance;
        vm = ubpf_create();
        assert(vm && !ls_map_glue_install(vm));
        char *error = NULL;
        assert(!ubpf_load_elf_ex(vm, object, (size_t)length, "request_candidate", &error));
        assert(!g_ls_config.load_error);
        jit = ubpf_compile_ex(vm, &error, ExtendedJitMode);
        if (!jit) { fprintf(stderr, "%s\n", error); return 1; }
        assert(!ls_config_bind(&g_ls_config, 8, r.instance, r.program_sha256));
        call(1, request, sizeof request - 1, mode);
        assert(last.flags == 2);
        uint64_t token = 101;
        r.revision = 1;
        memcpy(r.rows, &token, 8);
        assert(!ls_config_publish(&g_ls_config, 8, &r, 112));
        call(1, request, sizeof request - 1, mode);
        assert(last.flags == 4);
        seed(1, 0, 1);
        call(1, request, sizeof request - 1, mode);
        assert(last.flags == 1 && last.path == 1 && last.lifetime == 1 && last.attempt == 1);
        assert(!memcmp(last.nonce, nonce, 32) && last.total == sizeof request - 5);
        seed(1, 1, 1);
        call(1, "POST /mcp HTTP/1.1\r\n\r\n", 22, mode);
        assert(last.flags == 512 && last.attempt == 2);
        seed(2, 1, 3);
        for (size_t i = 0; i < sizeof request - 5; i++) {
            call(1, request + i, 1, mode);
            assert(last.lifetime == 2 && last.attempt == 1);
            assert(last.flags == (i == sizeof request - 6 ? 1u : 0u));
        }
        assert(!memcmp(last.nonce, nonce, 32));
        seed(3, 0, 1);
        call(1, (void *)1, 30, mode);
        assert(last.flags == 16);
        seed(4, 0, 1);
        call(1, "HTTP/1.1 200 OK\r\n\r\n", 19, mode);
        assert(last.flags == 8);
        char duplicate[256] = {0};
        int n = snprintf(duplicate, sizeof duplicate,
                "POST /mcp HTTP/1.1\r\nX-Proof-Nonce: %s\r\nx-proof-nonce: %s\r\n\r\n", nonce, nonce);
        seed(5, 0, 1);
        call(1, duplicate, n, mode);
        assert(last.flags == 128);
        seed(6, 0, 1);
        call(1, "POST /mcp HTTP/1.1\r\nX-Proof-Nonce: z\r\n\r\n", 40, mode);
        assert(last.flags == 64);
        char bounded[1024] = {0};
        for (unsigned size = 511; size <= 513; size++) {
            n = snprintf(bounded, sizeof bounded,
                    "POST /mcp HTTP/1.1\r\nX-Proof-Nonce: %s\r\nX-Fill: ", nonce);
            memset(bounded + n, 'x', size - n - 4);
            memcpy(bounded + size - 4, "\r\n\r\n", 4);
            seed(10 + size - 511, 0, 1);
            call(1, bounded, size, mode);
            assert(last.flags == (size <= 512 ? 1u : 256u));
            assert(last.total == (size <= 512 ? size : 512));
        }
        seed(128, 0, 1);
        call(1, request, sizeof request - 1, mode);
        assert(last.flags == 256);
        seed(20, 0, 0);
        call(1, request, sizeof request - 1, mode);
        assert(last.flags == 4);
        seed(21, 0, 1);
        reject_output = 1;
        call(1, request, sizeof request - 1, mode);
        assert(last.failures == 0);
        reject_output = 0;
        seed(22, 0, 1);
        call(1, request, sizeof request - 1, mode);
        assert(last.flags == 1 && last.failures == 1);
        ubpf_destroy(vm);
        printf("PASS %s: bounded extraction, every-byte fragmentation, body exclusion, "
                "bounds 511/512/513, missing/duplicate/invalid nonce, response, "
                "read failure, output refusal, absent/ended/reused lifetime, fresh attempt\n",
                mode ? "JIT" : "interpreter");
    }
    free(object);
    return 0;
}

substrate/check_template.c.text:
/* Tutorial oracle. Native fixture types differ from the bytecode's views.
 * Runs real uBPF and general helpers. Only the output sink is a test double.
 * This is a bench test, not a TMM build or a traffic test.
 */
#define LS_MAP_GLUE_IMPL 1
#include "ls_map_glue.h"
#include <assert.h>
#include <stddef.h>

struct http_parser { uint64_t pad[3]; uint32_t header_count; };
struct http_parse_ctx {
    uint64_t pad[2];
    struct http_parser *parser;
    unsigned char pad2[7], version_num;
};
struct xbuf { uint64_t pad[2]; uint32_t len; };
static struct http_parser parser = {.header_count = 91};
static struct http_parse_ctx http = {.parser = &parser, .version_num = 1};
static struct xbuf buffer = {.len = 123};

/* Independent wire mirror; do not include the program's definitions. */
struct event {
    uint32_t magic, abi;
    uint64_t instance, revision, monotonic_ns, seen;
    uint64_t observed, threshold, result;
    uint32_t kind, flags, version, header_count, matched, verdict;
};
static struct event last;
static unsigned emissions, reject_emit;
static struct ls_config_request request;

int ls_tp_publish_raw(int slot, const void *data, unsigned long size)
{
    assert(slot == 5 && size == 88 && sizeof last == 88);
    memcpy(&last, data, sizeof last);
    assert(last.magic == 0x544d4d31 && last.abi == 1);
    emissions++;
    return reject_emit ? -1 : 0;
}

static void publish(uint64_t threshold, uint64_t reserved, uint64_t reset,
                    uint32_t flags, uint32_t schema)
{
    uint64_t row[4] = {threshold, reserved, reset, flags};
    request.expected_revision = g_ls_config.slots[5].current.revision;
    request.revision = request.expected_revision + 1;
    request.schema = schema;
    memcpy(request.rows[0], row, sizeof row);
    assert(!ls_config_publish(&g_ls_config, 5, &request, 112));
}

static uint64_t call(struct ubpf_vm *vm, ubpf_jit_ex_fn jit,
                     uint64_t *ctx, int native)
{
    uint64_t ret = 0;
    uint8_t stack[4096] = {0};
    emissions = 0;
    g_ls_cur_slot = 5;
    ls_config_begin(&g_ls_config_view, 5);
    if (native)
        ret = jit(ctx, 96, stack, sizeof stack);
    else
        assert(!ubpf_exec_ex(vm, ctx, 96, &ret, stack, sizeof stack));
    g_ls_config_view.active = 0;
    g_ls_cur_slot = -1;
    return ret;
}

int main(int argc, char **argv)
{
    if (argc == 2 && !strcmp(argv[1], "--offsets")) {
        printf("{\"http_parse_ctx\":{\"version_num\":%zu,\"parser\":%zu},"
               "\"http_parser\":{\"header_count\":%zu},"
               "\"xbuf\":{\"len\":%zu}}\n",
               offsetof(struct http_parse_ctx, version_num),
               offsetof(struct http_parse_ctx, parser),
               offsetof(struct http_parser, header_count),
               offsetof(struct xbuf, len));
        return 0;
    }
    assert(argc == 3);
    int exit_hook = !strcmp(argv[2], "exit");
    FILE *file = fopen(argv[1], "rb");
    assert(file && !fseek(file, 0, SEEK_END));
    long len = ftell(file);
    assert(len > 0 && !fseek(file, 0, SEEK_SET));
    void *object = malloc((size_t)len);
    assert(object && fread(object, 1, (size_t)len, file) == (size_t)len);
    fclose(file);
    g_ls_config.session = 42;
    request.abi = request.entries = 1;
    request.session = 42;
    request.instance = ls_config_new_instance(&g_ls_config, 5);
    memset(request.program_sha256, 0xab, 32);
    struct ubpf_vm *vm = ubpf_create();
    char *error = NULL;
    assert(vm);
    g_ls_config.loading = request.instance;
    assert(!ls_map_glue_install(vm));
    assert(!ubpf_load_elf_ex(vm, object, (size_t)len, "template", &error));
    assert(!g_ls_config.load_error);
    ubpf_jit_ex_fn jit = ubpf_compile_ex(vm, &error, ExtendedJitMode);
    if (!jit) { fprintf(stderr, "%s\n", error); return 1; }
    uint64_t ctx[12] = {(uintptr_t)&http, (uintptr_t)&buffer, 0, 0, 0, 123};
    /* Poison exit argument pointers: a valid exit observer must ignore them. */
    if (exit_hook) ctx[0] = ctx[1] = 1;
    for (int mode = 0; mode < 2; mode++) {
        assert(!ls_config_bind(&g_ls_config, 5, request.instance,
                               request.program_sha256));
        assert(call(vm, jit, ctx, mode) == 0 && emissions == 1);
        assert(last.flags == 1 && last.revision == 0);
        /* The retired schema and a nonzero reserved word must be refused. */
        publish(100, 0, (uint64_t)mode + 1, 3, 1);
        assert(call(vm, jit, ctx, mode) == 0 && last.flags == 2);
        publish(100, UINT64_MAX, (uint64_t)mode + 1, 3, 2);
        assert(call(vm, jit, ctx, mode) == 0 && last.flags == 2 && emissions == 1);
        publish(100, 0, (uint64_t)mode + 1, 3, 2);
        uint64_t want = exit_hook ? 0 : 1;
        uint64_t got = call(vm, jit, ctx, mode);
        /* A non-assert failure lets the runner test the unrelocated falsifier. */
        if (got != want || emissions != 1 || last.flags || last.observed != 123 || last.seen != 1 ||
            (!exit_hook && (last.version != 1 || last.header_count != 91))) {
            printf("MISMATCH native fields: ret=%llu emissions=%u flags=%u "
                   "observed=%llu seen=%llu version=%u headers=%u\n",
                   (unsigned long long)got, emissions, last.flags,
                   (unsigned long long)last.observed,
                   (unsigned long long)last.seen, last.version,
                   last.header_count);
            return 1;
        }
        assert(last.matched && last.monotonic_ns && last.kind == (exit_hook ? 2u : 1u));
        assert(last.result == (exit_hook ? 123u : 0u));
        publish(200, 0, (uint64_t)mode + 1, 3, 2);
        assert(call(vm, jit, ctx, mode) == 0 && last.seen == 2 && !last.matched && emissions == 1);
        /* Every rapid call must attempt output, including nonmatches. */
        for (unsigned i = 0; i < 128; i++)
            assert(call(vm, jit, ctx, mode) == 0 && emissions == 1 && last.seen == i + 3);
        publish(100, 0, 100 + (uint64_t)mode, 3, 2);
        reject_emit = 1;
        assert(call(vm, jit, ctx, mode) == want && emissions == 1 && last.seen == 1);
        assert(call(vm, jit, ctx, mode) == want && emissions == 1 && last.seen == 2);
        reject_emit = 0;
        assert(call(vm, jit, ctx, mode) == want && emissions == 1 && last.seen == 3);
        publish(100, 0, 100 + (uint64_t)mode, 0, 2);
        assert(call(vm, jit, ctx, mode) == 0 && last.flags == 32 && emissions == 1);
        publish(100, 0, 100 + (uint64_t)mode, 1, 2);
        assert(call(vm, jit, ctx, mode) == 0 && last.seen == 1 && last.matched);
        if (!exit_hook) {
            ctx[0] = 0;
            assert(call(vm, jit, ctx, mode) == 0 && last.flags == 4);
            ctx[0] = (uintptr_t)&http;
            http.parser = (void *)1;
            assert(call(vm, jit, ctx, mode) == 0 && last.flags == 4);
            http.parser = &parser;
        }
        /* A stale state entry must reset, even with the same reset token. */
        for (uint32_t i = 0; i < atomic_load(&g_ls_nshapes); i++) {
            if (!strcmp(g_ls_names[i], "tutorial_state")) {
                uint32_t key = 0;
                uint64_t *state = ls_map_lookup(ls_map_get(ls_map_current(), i),
                                                (const uint8_t *)&key);
                assert(state);
                state[0] = 0;
            }
        }
        assert(call(vm, jit, ctx, mode) == 0 && last.seen == 1);
        printf("PASS %s %s: input, revision, fields, count, reset, delete, "
               "every-call output, output refusal, verdict, stale state\n",
               mode ? "JIT" : "interpreter", argv[2]);
    }
    printf("EVENT {\"hook\":\"prog\",\"slot\":5,\"len\":88,\"data\":\"");
    for (size_t i = 0; i < sizeof last; i++)
        printf("%02x", ((const unsigned char *)&last)[i]);
    puts("\"}");
    ubpf_destroy(vm);
    free(object);
    return 0;
}

substrate/check_json_initialization.c.text:
/* Exact JSON guard cases through the production VM and shadow-frame dispatch. */
#define LS_MAP_GLUE_IMPL
#include "ls_vm.c"
#include "ls_fexit.h"
#include "surfaces/json_initialization_abi.h"
#include <assert.h>
char ls_fexit_stub[1];
static struct ji_event last;
static unsigned emissions, reads, bytes, fail_read, refuse;
static struct ls_config_request request;
static _Alignas(64) unsigned char node[192], flow[64];

int ls_tp_publish_raw(int slot, const void *record, unsigned long length)
{
    assert(slot == 1 && length == sizeof last);
    memcpy(&last, record, length); emissions++;
    return refuse ? -1 : 0;
}
int ls_tp_emit_shield(int slot, unsigned gen, unsigned mode, unsigned verdict,
                      const void *ctx, unsigned long length)
{
    (void)slot; (void)gen; (void)mode; (void)verdict; (void)ctx; (void)length;
    assert(!"initialization program selected enforcement");
    return -1;
}
static uint64_t tracked_read(uint64_t dst, uint64_t n, uint64_t src,
                              uint64_t a4, uint64_t a5)
{
    reads++; bytes += n;
    if (fail_read && reads == fail_read) return 1;
    return ls_h_probe_read(dst, n, src, a4, a5);
}
static void put32(unsigned char *p, uint32_t value)
{
    memcpy(p, &value, 4);
}
static void invoke(uint64_t address, unsigned event, uint64_t uf,
                    unsigned status, unsigned action)
{
    uint64_t args[6] = {address, event, uf, 0, 0, 0};
    uint64_t return_slot = 0x12345678;
    unsigned char before[sizeof node] = {0};
    memcpy(before, node, sizeof node);
    emissions = reads = bytes = 0;
    if (action == 5) g_slots[1].armed = false;
    ls_fexit_enter(1, &return_slot, args);
    assert(emissions == 0 && !memcmp(before, node, sizeof node));
    assert(return_slot == (uintptr_t)ls_fexit_stub);
    if (action == 1) put32(node + 152, 1);
    if (action == 2) put32(node + 152, 0);
    if (action == 3) {
        request.expected_revision = request.revision++;
        assert(!ls_config_publish(&g_ls_config, 1, &request, 112));
    }
    if (action == 4) assert(!mprotect((void *)address, 4096, PROT_NONE));
    if (action == 5) g_slots[1].armed = true;
    unsigned entry_reads = reads;
    memcpy(before, node, sizeof node);
    assert(ls_fexit_leave((uintptr_t)(&return_slot + 1), UINT64_MAX) == 0x12345678);
    assert(reads == entry_reads && emissions == 1);
    assert(!memcmp(before, node, sizeof node));
    assert(last.magic == JI_MAGIC && last.status == status);
    assert(last.reads == reads && last.source_bytes == bytes);
    assert(reads <= 3 && bytes <= 9);
    printf("RECORD ");
    for (size_t i = 0; i < sizeof last; i++) printf("%02x", ((unsigned char *)&last)[i]);
    puts("");
}
int main(int argc, char **argv)
{
    assert(argc == 2);
    FILE *file = fopen(argv[1], "rb");
    assert(file && !fseek(file, 0, SEEK_END));
    long length = ftell(file);
    assert(length > 0 && !fseek(file, 0, SEEK_SET));
    void *blob = malloc((size_t)length);
    assert(blob && fread(blob, 1, (size_t)length, file) == (size_t)length);
    assert(!fclose(file));
    assert(ls_vm_init());
    g_ls_config.session = 42;
    request.abi = request.schema = request.entries = 1;
    request.session = 42; request.revision = 1;
    request.instance = ls_config_new_instance(&g_ls_config, 1);
    memset(request.program_sha256, 1, sizeof request.program_sha256);
    request.rows[0][0] = 123;
    g_ls_config.loading = request.instance;
    assert(ls_vm_reload(1, blob, (size_t)length, "fexit/snapshot/hud_json_handler",
                        "json_initialization", LS_MODE_MONITOR) == 1);
    g_ls_config.loading = 0;
    assert(!ubpf_register(g_slots[1].vm, 4, "tracked_read", tracked_read));
    assert(!ls_config_bind(&g_ls_config, 1, request.instance, request.program_sha256));
    put32(node + 44, 0xc00060); flow[37] = 0x40;
    invoke((uintptr_t)node, 57, (uintptr_t)flow, 6, 0);
    assert(last.flags == 2 && !reads && !last.sequence);
    assert(!ls_config_publish(&g_ls_config, 1, &request, 112));
    invoke((uintptr_t)node, 57, (uintptr_t)flow, 1, 0);
    assert(last.guards == 3 && last.flow_side == 1 && last.sequence == 1);
    flow[37] = 0x80;
    invoke((uintptr_t)node, 57, (uintptr_t)flow, 1, 0);
    assert(last.flow_side == 2);
    invoke((uintptr_t)node, 2, (uintptr_t)flow, 3, 0);
    assert(!reads && !last.guards);
    put32(node + 152, 1);
    invoke((uintptr_t)node, 57, (uintptr_t)flow, 2, 2);
    assert(last.guards == 1 && reads == 2);
    invoke((uintptr_t)node, 57, (uintptr_t)flow, 1, 1);
    put32(node + 152, 0);
    for (unsigned i = 0; i < 3; i++) {
        put32(node + 44, i == 0 ? 0x800060 : i == 1 ? 0xc0005f : 0x2c00060);
        invoke((uintptr_t)node, 57, (uintptr_t)flow, 5, 0);
    }
    put32(node + 44, 0xc00060);
    invoke(0, 57, (uintptr_t)flow, 0, 0);
    invoke((uintptr_t)node + 1, 57, (uintptr_t)flow, 5, 0);
    invoke((uintptr_t)node, 57, (uintptr_t)flow + 1, 5, 0);
    flow[37] = 0xc0;
    invoke((uintptr_t)node, 57, (uintptr_t)flow, 5, 0);
    flow[37] = 0x40;
    for (fail_read = 1; fail_read <= 3; fail_read++)
        invoke((uintptr_t)node, 57, (uintptr_t)flow, 4, 0);
    fail_read = 0;
    void *page = mmap(NULL, 4096, PROT_READ | PROT_WRITE,
                      MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    assert(page != MAP_FAILED);
    put32((unsigned char *)page + 44, 0xc00060);
    assert(ls_ranges_current(1));
    invoke((uintptr_t)page, 57, (uintptr_t)flow, 1, 4);
    assert(ls_ranges_current(1)); /* Fixture changed its mapping permissions. */
    invoke((uintptr_t)page, 57, (uintptr_t)flow, 4, 0);
    assert(!munmap(page, 4096));
    invoke((uintptr_t)node, 57, (uintptr_t)flow, 6, 3);
    assert(last.flags == 2);
    invoke((uintptr_t)node, 57, (uintptr_t)flow, 0, 5);
    assert(last.flags == 1);
    refuse = 1;
    invoke((uintptr_t)node, 57, (uintptr_t)flow, 1, 0);
    refuse = 0;
    invoke((uintptr_t)node, 57, (uintptr_t)flow, 1, 0);
    assert(last.output_failures == 1);
    assert(!g_ls_fexit_desync && !g_ls_fexit_reclaimed && !g_ls_fexit_overflow);
    assert(g_slots[1].safe_returns == 0);
    printf("PASS JSON initialization jit=%d cases=22\n", g_cfg.jit);
    ls_vm_fini(); free(blob);
    return 0;
}

substrate/check_target.c.text:
/* Exercise the runtime parser/check against independently produced ELF files. */
#include "ls_target.h"
#include <stdio.h>
#include <stdlib.h>

int main(int argc, char **argv)
{
    if (argc != 5) return 2;
    FILE *f = fopen(argv[1], "rb");
    if (!f || fseek(f, 0, SEEK_END)) return 2;
    long size = ftell(f);
    if (size < 0 || size > 1048576 || fseek(f, 0, SEEK_SET)) return 2;
    void *blob = malloc((size_t)size + 1);
    if (!blob || fread(blob, 1, (size_t)size, f) != (size_t)size) return 2;
    fclose(f);
    struct ls_target target;
    int rc = ls_target_parse(blob, (size_t)size, argv[2], argv[3], &target);
    free(blob);
    if (rc) return 1;
    if (ls_target_check_file(argv[4], &target)) return 1;
    printf("PASS target=0x%llx kind=%u pad=%u\n",
           (unsigned long long)target.entry, target.is_exit, target.pad_offset);
    return 0;
}

substrate/check_program_socket.c.text:
/* Actual program socket handler and prepare handoff, with authored functions.
 * Audit output is outside this test. The signature verifier is the real one. */
#include "ls_vm_load.c"
#include "ls_vm.c"
#include <assert.h>

unsigned bodies;
extern uint64_t program_alpha(uint64_t a, uint64_t b);
extern uint64_t program_beta(uint64_t a, uint64_t b);
static const char *build_id;
static _Atomic unsigned ready;
const char *ls_audit_build_id(void) { return build_id; }
void ls_audit_note_reply(const char *text) { (void)text; }
int ls_tp_publish_raw(int slot, const void *record, unsigned long length)
{ (void)slot; (void)record; (void)length; return 0; }
int ls_tp_emit_shield(int slot, unsigned gen, unsigned mode, unsigned verdict,
                      const void *ctx, unsigned long length)
{ (void)slot; (void)gen; (void)mode; (void)verdict; (void)ctx; (void)length; return 0; }
void ls_fexit_enter(void) { abort(); }
void ls_fexit_leave(void) { abort(); }

static void *prepare(void *unused)
{
    (void)unused;
    assert(ls_vm_init());
    ls_prep_timer_on = 1;
    atomic_store(&ready, 1);
    for (;;) {
        ls_prep_run_pending();
        struct timespec pause = {0, 1000000};
        nanosleep(&pause, NULL);
    }
    return NULL;
}

int main(int argc, char **argv)
{
    assert(argc == 3);
    assert(program_alpha(0, 0) == 0 && program_beta(0, 0) == 10);
    build_id = argv[2];
    g_ls_config.session = 1;
    pthread_t thread;
    assert(!pthread_create(&thread, NULL, prepare, NULL));
    while (!atomic_load(&ready)) {
        struct timespec pause = {0, 1000000};
        nanosleep(&pause, NULL);
    }
    int server = socket(AF_UNIX, SOCK_STREAM, 0);
    struct sockaddr_un address = {.sun_family = AF_UNIX};
    assert(server >= 0 && strlen(argv[1]) < sizeof address.sun_path);
    strcpy(address.sun_path, argv[1]);
    assert(!bind(server, (struct sockaddr *)&address, sizeof address));
    assert(!chmod(argv[1], 0600) && !listen(server, 4));
    puts("READY"); fflush(stdout);
    for (;;) {
        int fd = accept(server, NULL, NULL);
        assert(fd >= 0);
        struct shield_msg *seen = NULL, copy;
        handle_msg(fd, &seen, &copy);
        close(fd);
    }
}

