/*
 * ls_fexit.h --- the function-exit trampoline's shadow-stack interface.
 *
 * The per-slot exit trampolines (ls_fexit_slot<n>, in trampoline_x86_64.S) call
 * ls_fexit_enter / ls_fexit_leave; the harness (check_fexit.c) reads the log and
 * counters. See ls_fexit.c.
 *
 * All mutable state is a single per-instance block of g_ls_fexit_* globals ---
 * one VM per core-pinned run-to-completion TMM instance, so no lock, and the
 * whole set is what the TMM globals whitelist must carry (like g_ls_audit).
 */
#ifndef LS_FEXIT_H
#define LS_FEXIT_H

#include <stdint.h>
#include "ls_vm.h"

#define LS_FEXIT_LOG 64u        /* recent exits kept for inspection */

/* The exit payload retains arg[0..4] at bytes 0..39 and ret at bytes 40..47.
 * fexit/ selects the same 96-byte tracing descriptor as fentry/, so the rest
 * must also be allocated and zeroed before calling the program. */
struct ls_ctx_exit {
    uint64_t arg[5];            /* rdi..r8, as the entry ctx           */
    uint64_t ret;              /* the hooked function's return value  */
    uint64_t reserved[LS_TRACING_CTX_SIZE / sizeof(uint64_t) - 6];
};
_Static_assert(sizeof(struct ls_ctx_exit) == LS_TRACING_CTX_SIZE,
               "exit context must cover the verifier's tracing region");
_Static_assert(offsetof(struct ls_ctx_exit, ret) == 40,
               "exit return-value offset must not change");
_Static_assert(offsetof(struct ls_ctx_exit, reserved) == 48,
               "exit payload must remain 48 bytes");

/* One observed exit: what the exit program would have been handed, plus which
 * slot's program it was. */
struct ls_fexit_event {
    uint64_t seq;               /* which enter this paired with           */
    int      slot;              /* which exit-program slot                */
    uint64_t retval;            /* the hooked function's return value      */
    uint64_t args[6];           /* rdi..r9 captured at entry               */
};

/* Called from the per-slot exit trampoline. `slot` is which exit-program to run
 * at leave; `slot_addr` is the caller-return to hijack; `args` the saved rdi..r9. */
void     ls_fexit_enter(int slot, uint64_t *slot_addr, const uint64_t *args);
uint64_t ls_fexit_leave(uint64_t cur, uint64_t retval);

/* Clear all state between test cases (and at instance init). */
void ls_fexit_reset(void);

/* Per-instance state / observability (defined in ls_fexit.c). */
extern struct ls_fexit_event g_ls_fexit_log[LS_FEXIT_LOG];
extern unsigned g_ls_fexit_log_n;
extern uint64_t g_ls_fexit_exits;
extern uint64_t g_ls_fexit_reclaimed;
extern uint64_t g_ls_fexit_overflow;
extern uint64_t g_ls_fexit_desync;

#endif /* LS_FEXIT_H */

substrate/ls_swap.c.text:
/* ls_swap.c --- rewrite five bytes of LIVE code while other cores run it.
 *
 * This is the kernel s text_poke_bp protocol (arch/x86/kernel/alternative.c),
 * in userspace: INT3 over byte 0, serialise every core, write the 4-byte tail,
 * serialise, write the real opcode over the INT3, serialise. A SIGTRAP handler
 * covers any core caught standing on the breakpoint mid-patch.
 *
 * Proven on this hardware against real private .text under 15-core contention:
 * ~12.5B calls, 0 corrupt returns; the naive orderings fault in the millions.
 * There is NO safe 5-byte store ordering --- the INT3 step is required, not
 * gold-plating.
 */
#define _GNU_SOURCE
#include <stdint.h>
#include <stdio.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <ucontext.h>
#include <sys/syscall.h>
#include <linux/membarrier.h>
#include "ls_arm.h"

static uint8_t *volatile g_pad;   /* read by the handler on other cores */                    /* the window, set only during a swap */
static struct sigaction g_prev;
static int g_installed;

static void ls_sync_cores(void)
{
    syscall(SYS_membarrier, MEMBARRIER_CMD_PRIVATE_EXPEDITED_SYNC_CORE, 0, 0);
}

/* A core that fetched our INT3 lands here; send it to the function body, i.e.
 * it behaves as UNARMED for that one in-flight call. Anything else is not ours
 * and must chain to TMM own handler (crashagent) --- never swallowed. */
static void
ls_swap_trap(int sig, siginfo_t *si, void *uc)
{
    ucontext_t *c = (ucontext_t *)uc;
    uint8_t *rip = (uint8_t *)c->uc_mcontext.gregs[REG_RIP];
    uint8_t *pad = __atomic_load_n(&g_pad, __ATOMIC_ACQUIRE);
    if (pad != NULL && rip == pad + 1) {
        c->uc_mcontext.gregs[REG_RIP] = (greg_t)(uintptr_t)(pad + 5);
        return;
    }
    if ((g_prev.sa_flags & SA_SIGINFO) && g_prev.sa_sigaction) {
        g_prev.sa_sigaction(sig, si, uc); return;
    }
    if (g_prev.sa_handler && g_prev.sa_handler != SIG_DFL && g_prev.sa_handler != SIG_IGN) {
        g_prev.sa_handler(sig); return;
    }
    _exit(133);
}

void
ls_swap_trap_install(void)
{
    if (g_installed)
        return;
    syscall(SYS_membarrier, MEMBARRIER_CMD_REGISTER_PRIVATE_EXPEDITED_SYNC_CORE, 0, 0);
    struct sigaction sa;
    memset(&sa, 0, sizeof sa);
    sa.sa_sigaction = ls_swap_trap;
    sa.sa_flags = SA_SIGINFO | SA_RESTART;
    sigaction(SIGTRAP, &sa, &g_prev);
    g_installed = 1;
}

/* /proc/self/mem: the debugger path into our own r-xp text. Proven to reach the
 * EXECUTED bytes on real TMM text (4 KB pages). */
static int
ls_poke(uint8_t *at, const void *src, size_t n)
{
    int fd = open("/proc/self/mem", O_RDWR);
    if (fd < 0) return -1;
    ssize_t w = pwrite(fd, src, n, (off_t)(uintptr_t)at);
    close(fd);
    return (w == (ssize_t)n) ? 0 : -1;
}

int
ls_swap_write5(uint8_t *pad, const uint8_t bytes[5])
{
    static const uint8_t int3 = 0xcc;
    ls_swap_trap_install();
    __atomic_store_n(&g_pad, pad, __ATOMIC_RELEASE);

    if (ls_poke(pad, &int3, 1) != 0) { __atomic_store_n(&g_pad, NULL, __ATOMIC_RELEASE); return -1; }
    ls_sync_cores();
    if (ls_poke(pad + 1, bytes + 1, 4) != 0) { __atomic_store_n(&g_pad, NULL, __ATOMIC_RELEASE); return -1; }
    ls_sync_cores();
    if (ls_poke(pad, bytes, 1) != 0) { __atomic_store_n(&g_pad, NULL, __ATOMIC_RELEASE); return -1; }
    ls_sync_cores();

    __atomic_store_n(&g_pad, NULL, __ATOMIC_RELEASE);
    __builtin___clear_cache((char *)pad, (char *)pad + 5);
    return 0;
}

