/* ls_core_relo.h --- CO-RE field-offset relocation for the loader.
 *
 * A portable program (surface/shield) names TMM fields by struct+field NAME and
 * carries .BTF + .BTF.ext relocation records. At load, ls_core_relocate() resolves
 * each field's byte offset against THIS build's BTF and patches the instruction
 * immediate --- so one bytecode runs on any build, no baked offsets, no rebuild.
 *
 * Scope: kind=0 FIELD_BYTE_OFFSET, the only kind our compiler emits for
 * preserve_access_index field reads. Every other kind is rejected (fail-dark).
 *
 * Runs on the TMM thread (via ls_prep_run_pending -> ls_vm_reload), where malloc
 * is legal; it is NOT safe on the loader pthread.
 */
#ifndef LS_CORE_RELO_H
#define LS_CORE_RELO_H

#include <stdint.h>

/* Parsed BTF: a type-id -> byte-offset index over an in-memory BTF blob.
 * The blob must outlive the struct (not copied). Free idx with free(). */
struct btf {
    const uint8_t *types;  uint32_t types_len;
    const char    *strs;   uint32_t strs_len;
    uint32_t      *idx;    uint32_t nids;   /* idx[id] = byte offset in types[] */
};

/* Parse a BTF blob (the target build's BTF, or a program's local .BTF) into `b`.
 * Returns 0 on success, <0 on a malformed blob. Allocates b->idx (free() it). */
int ls_core_btf_open(struct btf *b, const uint8_t *blob, uint32_t len);
void ls_core_btf_free(struct btf *b);

/* Find the `.BTF` section span inside an ELF64 blob (bounds-checked). On success
 * sets *btf and *btf_sz to point into `elf` and returns 0; returns <0 if the ELF is
 * malformed or has no `.BTF` section. Used to read the running binary's own BTF
 * from /proc/self/exe --- the kernel's "embed .BTF in vmlinux" model for a
 * userspace process. */
int ls_core_btf_find_in_elf(const uint8_t *elf, uint32_t elf_len,
                            const uint8_t **btf, uint32_t *btf_sz);

/* 1 if the program object carries `.BTF.ext` (so it needs relocating), 0 if it does
 * not, -1 if the ELF cannot be walked. Asked BEFORE the target BTF is demanded, so
 * a program whose offsets were resolved at sign time --- and whose `.BTF`/`.BTF.ext`
 * were therefore stripped --- is not refused for lacking type information it does
 * not use. Treat -1 as "needs relocation": see the note in ls_core_relo.c. */
int ls_core_elf_has_relos(const uint8_t *elf, uint32_t elf_len);

/* Relocate `elf` (an eBPF program object, MUTABLE) in place against `target`.
 * Parses the program's own .BTF/.BTF.ext, resolves every FIELD_BYTE_OFFSET record
 * by field name against `target`, and patches the instruction immediates.
 * Returns 0 iff EVERY record resolved and was patched; <0 (and leaves the object
 * untrusted) if the object is malformed, carries an unsupported record kind, or a
 * field is absent in the target --- the caller MUST refuse to load on <0.
 * n_out (optional) receives the number of records relocated. */
int ls_core_relocate(void *elf, uint32_t elf_len, const struct btf *target,
                     unsigned *n_out);

/* relocation result codes (negated on return) */
enum {
    LS_RELO_OK            = 0,
    LS_RELO_EBADELF       = 1,   /* ELF header/section table out of bounds        */
    LS_RELO_ENOBTF        = 2,   /* program lacks .BTF/.BTF.ext                    */
    LS_RELO_EBADBTF       = 3,   /* malformed local BTF or .BTF.ext               */
    LS_RELO_EKIND         = 4,   /* unsupported relocation kind                   */
    LS_RELO_ENOFIELD      = 5,   /* field/struct absent in target, or bitfield    */
    LS_RELO_EBOUNDS       = 6,   /* insn offset outside its program section       */
};

#endif /* LS_CORE_RELO_H */

substrate/check_json.c.text:
/* check_json.c --- does the drain agent's output survive a hostile cause string?
 *
 * WHY THIS EXISTS. Until Phase 3 the agent emitted string fields with a bare
 * "%s". That was safe by accident: the only string in a record was a __FILE__
 * basename, always [a-z0-9_.]. Phase 3 forwards rst_why's sixth argument --- the
 * human-written cause, and at flow_table.c an entry from a runtime table --- and a
 * quote, a backslash or a control byte in any of those makes the whole line
 * unparseable.
 *
 * The failure would not appear here. It appears in whatever consumes the stream,
 * as a parse error blamed on the producer, hours later, with no record of which
 * line did it. So the escaping is asserted at build time.
 *
 * The assertions below check the ESCAPING RULES; check-json in the Makefile then
 * pipes the same output through a real JSON parser, because a hand-written escaper
 * that satisfies a hand-written test proves very little on its own.
 */
#include <assert.h>
#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <unistd.h>

#include "ls_json.h"

static char cap[512];

/* ls_json_str writes to stdout; redirect it into a buffer with a memstream so the
 * escaper needs no modification to be testable. */
static const char *
esc(const char *in, unsigned int n)
{
    FILE *ms;
    FILE *saved = stdout;
    size_t len = 0;
    char *buf = NULL;

    ms = open_memstream(&buf, &len);
    assert(ms != NULL);
    stdout = ms;
    ls_json_str(in, n);
    fflush(ms);
    stdout = saved;
    fclose(ms);

    assert(len < sizeof cap);
    memcpy(cap, buf, len);
    cap[len] = 0;
    free(buf);
    return cap;
}

/* Under -DLS_JSON_DUMP, print the hostile inputs as real JSON lines instead of
 * asserting, so the Makefile can hand them to python's parser. Same escaper, same
 * inputs --- the difference is who judges the output. */
#ifdef LS_JSON_DUMP
static void
dump(const char *in, unsigned int n)
{
    printf("{\"cause\":\"");
    ls_json_str(in, n);
    printf("\"}\n");
}

int
main(void)
{
    char hi[4]; hi[0] = 'a'; hi[1] = (char)0xff; hi[2] = 'b'; hi[3] = 0;
    char ctl[4]; ctl[0] = 'x'; ctl[1] = (char)0x01; ctl[2] = 'y'; ctl[3] = 0;
    dump("Closing", 7);
    dump("say \"hi\" and \\ that", 18);
    dump("line\nbreak\ttab\rcr", 17);
    dump(hi, 3);
    dump(ctl, 3);
    dump("No pool member available", 24);
    return 0;
}
#else

int
main(void)
{
    int n = 0;

    /* 1. ordinary text passes through unchanged --- escaping must not corrupt the
     *    overwhelmingly common case */
    assert(strcmp(esc("Closing", 7), "Closing") == 0);                        n++;
    assert(strcmp(esc("TCP RST from remote system", 26),
                  "TCP RST from remote system") == 0);                        n++;

    /* 2. the two characters that break JSON outright */
    assert(strcmp(esc("say \"hi\"", 8), "say \\\"hi\\\"") == 0);              n++;
    assert(strcmp(esc("a\\b", 3), "a\\\\b") == 0);                            n++;

    /* 3. control characters JSON forbids raw, with their short forms */
    assert(strcmp(esc("a\nb", 3), "a\\nb") == 0);                             n++;
    assert(strcmp(esc("a\rb", 3), "a\\rb") == 0);                             n++;
    assert(strcmp(esc("a\tb", 3), "a\\tb") == 0);                             n++;

    /* 4. anything else non-printable becomes \uXXXX. The record is a fixed-size
     *    field captured on a teardown path --- there is no guarantee it holds UTF-8,
     *    so bytes are escaped rather than passed through and hoped over. */
    assert(strcmp(esc("a\x01" "b", 3), "a\\u0001b") == 0);                     n++;
    assert(strcmp(esc("a\x7f" "b", 3), "a\\u007fb") == 0);                     n++;
    /* 0xff written via an array, not "a\xffb": that spells one hex escape "\xffb"
     * which is out of range for a char and fails -Werror. The high byte is the
     * interesting case precisely because the field is not guaranteed UTF-8. */
    {
        char hi[4]; hi[0] = 'a'; hi[1] = (char)0xff; hi[2] = 'b'; hi[3] = 0;
        assert(strcmp(esc(hi, 3), "a\\u00ffb") == 0);                          n++;
    }

    /* 5. bounded by BOTH the length and a NUL --- the field is fixed-size and may
     *    be either fully used or short. Reading past file_len into the next field
     *    is exactly the bug the length exists to prevent. */
    assert(strcmp(esc("abcdefgh", 3), "abc") == 0);                           n++;
    assert(strcmp(esc("ab\0cd", 5), "ab") == 0);                              n++;
    assert(strcmp(esc("", 0), "") == 0);                                      n++;

    /* 6. a cause made entirely of hostile bytes still terminates and stays bounded */
    {
        char hostile[41];
        unsigned int i;
        for (i = 0; i < sizeof hostile - 1; i++)
            hostile[i] = (char)(i % 2 ? '"' : '\\');
        hostile[sizeof hostile - 1] = 0;
        const char *out = esc(hostile, sizeof hostile - 1);
        /* every byte escaped to two, none dropped */
        assert(strlen(out) == (sizeof hostile - 1) * 2);                      n++;
    }

    printf("ok    ls_json.h  (%d assertions: quote, backslash, control bytes, "
           "\\uXXXX, length- and NUL-bounded)\n", n);
    return 0;
}
#endif /* LS_JSON_DUMP */

