/* ls_tp_ring.h --- the shared-memory segment the tracepoint publishes into.
 *
 * ls_ring.h is the ring: lock-free, bounded, 15 assertions, TSan clean. It has
 * never run inside TMM. This file is the missing half --- the segment that holds
 * the rings, who creates it, and which ring a given thread writes to.
 *
 * WHY SHARED MEMORY IS FORCED, NOT PREFERRED. TMM aliases malloc to a per-core
 * allocator whose spinlock is never initialised on a thread TMM did not create,
 * so a drain agent that allocates spins forever. Everything here is mmap.
 * Equally, the consumer must live in another process: a broker client linked
 * into TMM would put a socket, a reconnect and a stalled subscriber inside the
 * poll loop. TMM writes bytes and forgets; the agent maps them read-only and
 * publishes. It can crash without TMM noticing.
 *
 * ONE RING PER THREAD, BY CONSTRUCTION. ls_ring.h is single-producer --- that is
 * what lets it be lock-free, and it is a correctness precondition, not a
 * performance note. g_slots in ls_vm.c is a plain process-global despite
 * ls_prep.c describing "per-thread VM state", and the TMM process here runs
 * three threads. Whether more than one reaches the tracepoint is exactly the
 * kind of thing that has been assumed wrongly before, so each thread claims its
 * own ring by atomic index and writes only to that. The precondition then holds
 * whatever the thread model turns out to be.
 *
 * OFF UNLESS ASKED. Nothing here allocates, maps or executes unless LS_TP_RING
 * names a segment --- the same discipline as the loader socket. The shipped path
 * is a load of one pointer and a branch.
 */
#ifndef LS_TP_RING_H
#define LS_TP_RING_H

#include <fcntl.h>
#include <stdatomic.h>
#include <stdint.h>
#include <stdio.h>
#include <string.h>
#include <sys/mman.h>
#include <unistd.h>

#include "ls_tp.h"
#include "ls_ring.h"

#define LS_TP_SEG_MAGIC   0x4c53534547303031ull   /* "LSSEG001" */
/* Segment format version. ls_rec gained ts_ns, so a consumer built against
 * version 1 walks records at the wrong stride --- it must be REFUSED, not left to
 * decode plausible garbage. Checked in ls_tp_seg_open below. */
#define LS_TP_SEG_VERSION   2u
#define LS_TP_MAX_RINGS    16u
#define LS_TP_RING_BYTES   (64u * 1024u)          /* power of two --- ls_ring requires it */

/* Hook and schema identity live in ls_tp.h --- they are part of the
 * ls_tp_dispatch() contract, and the trampoline needs them without
 * dragging mmap and stdatomic in. */

/* Segment header, at offset 0. Rings follow at a fixed stride so a consumer can
 * find ring i without walking anything. */
struct ls_tp_seg {
    uint64_t magic;
    uint32_t version;
    uint32_t n_rings;
    uint32_t ring_stride;            /* bytes from one ring's start to the next */
    uint32_t ring_data_size;
    _Atomic uint32_t claimed;        /* how many threads have taken a ring      */
    uint32_t _pad;
};

#define LS_TP_STRIDE  ((uint32_t)sizeof(struct ls_ring) + LS_TP_RING_BYTES)
#define LS_TP_SEG_SZ  ((size_t)sizeof(struct ls_tp_seg) + \
                       (size_t)LS_TP_MAX_RINGS * LS_TP_STRIDE)

static inline struct ls_ring *
ls_tp_seg_ring(struct ls_tp_seg *s, uint32_t i)
{
    return (struct ls_ring *)((uint8_t *)s + sizeof(struct ls_tp_seg)
                              + (size_t)i * s->ring_stride);
}

/*
 * Create and map the segment. Idempotent and safe to call from every thread:
 * the loser of the race unmaps its own view and takes the winner's.
 *
 * Returns NULL when disabled or on any failure. EVERY failure path here is
 * non-fatal by design --- telemetry that can prevent TMM from starting is worse
 * than no telemetry.
 */
static inline struct ls_tp_seg *
ls_tp_seg_open(const char *path, int create)
{
    int fd, i;
    void *p;
    struct ls_tp_seg *s;

    if (path == NULL || *path == '\0')
        return NULL;

    fd = open(path, create ? (O_RDWR | O_CREAT) : O_RDWR, 0600);
    if (fd < 0)
        return NULL;

    if (create && ftruncate(fd, (off_t)LS_TP_SEG_SZ) != 0) {
        close(fd);
        return NULL;
    }

    p = mmap(NULL, LS_TP_SEG_SZ, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    close(fd);                        /* the mapping keeps the object alive */
    if (p == MAP_FAILED)
        return NULL;

    s = (struct ls_tp_seg *)p;
    if (!create) {
        if (s->magic != LS_TP_SEG_MAGIC || s->version != LS_TP_SEG_VERSION ||
            s->ring_stride != LS_TP_STRIDE) {
            munmap(p, LS_TP_SEG_SZ);
            return NULL;             /* wrong magic, wrong version, or wrong geometry */
        }
        return s;
    }

    /* Initialise every ring before publishing the magic, so a consumer that
     * opens mid-setup either sees no segment or sees a complete one. */
    s->version        = LS_TP_SEG_VERSION;
    s->n_rings        = LS_TP_MAX_RINGS;
    s->ring_stride    = LS_TP_STRIDE;
    s->ring_data_size = LS_TP_RING_BYTES;
    atomic_store_explicit(&s->claimed, 0, memory_order_relaxed);
    for (i = 0; i < (int)LS_TP_MAX_RINGS; i++)
        ls_ring_init(ls_tp_seg_ring(s, (uint32_t)i), LS_TP_RING_BYTES,
                     LS_RING_STREAM);

    /* STREAM, not RECORD, and the choice matters. A streaming analytic feed must
     * never have a record pulled out from under a mid-read consumer, and the
     * data plane must never wait on that consumer. Full therefore means drop the
     * NEW record and count it --- a counted gap, never a silent one, and never
     * backpressure into the poll loop. */

    __atomic_store_n(&s->magic, LS_TP_SEG_MAGIC, __ATOMIC_RELEASE);
    return s;
}

/*
 * The calling thread's own ring, claimed once and remembered.
 *
 * __thread rather than an index derived from a TMM thread id: the id is not
 * available in this include world, and a wrong index would silently give two
 * threads the same ring --- which does not crash, it corrupts records
 * occasionally, which is the worst way for this to be wrong.
 */
static inline struct ls_ring *
ls_tp_my_ring(struct ls_tp_seg *s)
{
    static __thread struct ls_ring *mine;
    static __thread int tried;
    uint32_t idx;

    if (mine != NULL || tried)
        return mine;
    tried = 1;                        /* claim at most once, even on failure */

    if (s == NULL)
        return NULL;

    idx = atomic_fetch_add_explicit(&s->claimed, 1, memory_order_relaxed);
    if (idx >= s->n_rings)
        return NULL;                  /* more threads than rings: this one is silent */

    mine = ls_tp_seg_ring(s, idx);
    return mine;
}

/*
 * Publish one record. Returns 1 if it landed, 0 if dropped or disabled.
 *
 * The entire cost on the hot path: a bounded memcpy and two ordered stores. No
 * allocation, no syscall, no lock --- which is the property that makes this
 * acceptable in a poll loop at all, and the one check_ring asserts by
 * construction rather than by inspection.
 */
static inline int
ls_tp_ring_publish(struct ls_tp_seg *seg, uint32_t hook_id, uint32_t schema_id,
                   uint32_t slot, uint64_t seq, uint64_t ts_ns,
                   const void *rec, uint32_t len)
{
    struct ls_ring *r = ls_tp_my_ring(seg);
    struct ls_rec h;

    if (r == NULL)
        return 0;

    h.hook_id   = hook_id;
    h.schema_id = schema_id;
    h.seq       = seq;
    h.slot      = slot;
    h.len       = len;
    h.ts_ns     = ts_ns;
    return ls_ring_emit(r, &h, rec, len);
}

#endif /* LS_TP_RING_H */

substrate/drain/ls_drain.c.text:
/* ls_drain --- the tracepoint's drain agent.
 *
 * Maps the shared segment, consumes records, writes them to stdout as JSON
 * lines, and acknowledges them so the rings stay open. That is the whole job.
 *
 * THE GOVERNING CONSTRAINT: TMM MUST NOT DEPEND ON THIS PROGRAM. Not on it
 * running, not on it keeping up, not on it exiting cleanly. Everything below
 * follows from that, and check_drain.c asserts it rather than trusting it:
 *
 *   - The producer never blocks on a consumer. ls_ring_emit on a full STREAM
 *     ring returns 0 and increments `drops`. There is no path in which TMM
 *     waits, retries, or errors because of anything here.
 *   - This agent NEVER writes to the ring's data area, only to consumer_pos.
 *   - It can be absent, killed mid-batch, or stalled indefinitely. The worst
 *     outcome is that rings fill and TMM counts drops --- a counted gap, which
 *     is the designed behaviour, not a failure.
 *
 * WHY NO BROKER CLIENT IS LINKED IN. Writing JSON lines to stdout and piping to a
 * publisher (or a file) keeps the *agent* free of a
 * broker dependency too. If the downstream pipe breaks, this process dies on
 * EPIPE, and TMM still does not care. Linking a reconnecting client here would
 * put retry logic one process closer to the data plane for no benefit, since the
 * decoupling that matters already happened at the shared-memory boundary.
 *
 *   ls_drain --segment /dev/shm/ls_tp_ring | <publisher>
 *
 * ON WHICH BROKER: BNK already runs RabbitMQ --- the f5-rabbit pod, reachable at
 * amqps://rabbitmq-server.default:5671. NATS appeared in earlier examples here and
 * is NOT deployed anywhere in the cluster, which made the comment read as a
 * recommendation for something absent. The choice stays outside this file either
 * way; that is the whole point of writing to stdout.
 *   ls_drain --segment /dev/shm/ls_tp_ring > records.jsonl
 *
 * DELIVERY CORRECTION, 2026-09-28. The old at-least-once claim was false:
 * ls_ring_consume advances consumer_pos BEFORE these output calls. A crash or
 * output failure can lose an already consumed record. The pinned /dev/full test
 * also shows exit zero despite failed output. See CONTESTED-PREMISES.md section 30.
 * Use ls_stream plus the acknowledged journal collector for commit-before-cursor
 * handoff. Its replay is limited by retention and source qualification. Slot and
 * sequence alone are not a globally unique identity across producer lifetimes.
 *
 * A HOSTILE OR BUGGY CONSUMER, stated plainly because it is a real boundary:
 * this process maps the segment read-write, because advancing consumer_pos
 * requires it. A consumer that writes a nonsense consumer_pos can therefore make
 * the producer's `prod - cons` underflow, which makes the full-check true
 * forever and turns the ring into a permanent drop-and-count. It cannot crash
 * TMM, corrupt TMM's memory, or block the data plane --- but it can silence its
 * own feed. Whoever can write this segment can already stop the telemetry by
 * not running; the segment is 0600 and this is a TMA item, not a hole.
 */
#define _GNU_SOURCE
#include <errno.h>
#include <fcntl.h>
#include <getopt.h>
#include <signal.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <time.h>
#include <unistd.h>

/* Escaping lives in its own header so check_json.c can test it. */
#include "../ls_json.h"

#include "../ls_tp_ring.h"

static volatile sig_atomic_t g_stop;
static void on_signal(int s) { (void)s; g_stop = 1; }

static const char *VERSION_NAME[4] = { "UNKNOWN", "HTTP/0.9", "HTTP/1.1", "HTTP/1.0" };

/* The 40-byte tmm:l7:http_headers record. Kept in the same order as
 * substrate/ls_tp_http.h; schema_id in each record is what authorises this
 * decode, and an unknown schema is emitted as raw rather than guessed at. */
struct http_rec {
    uint32_t parse_err;          /* the PARSER's verdict --- classify with this */
    uint32_t err;                /* the filter's final disposition, NOT the parse */
    uint32_t reject_reason, passthru, version, method;
    uint32_t header_count, status_code, invalid_flags, body_pos, hdr_bytes;
};

/* ERR_MORE_DATA is 17 --- headers spanning two packets. Not a fault, and the
 * reason `parse_err != 0` is the wrong test. */
#define ERR_VAL 3u
#define ERR_BOUNDS 5u
#define ERR_REJECT 16u
#define MALFORMED(r) ((r)->parse_err == ERR_VAL || (r)->parse_err == ERR_BOUNDS || \
                      (r)->parse_err == ERR_REJECT)

/* The three classes come apart, so name them rather than collapsing them. */
static const char *
klass(const struct http_rec *r)
{
    if (!MALFORMED(r))       return "normal";
    return r->passthru ? "waived" : "refused";
}

/* struct ls_ctx_rst --- substrate/ls_ctx_rst.h. The teardown record: which line
 * of TMM's own source decided to close this connection. */
struct rst_rec {
    uint32_t cookie_lo, cookie_hi;   /* TMM's flow cookie, split (align 4)   */
    uint32_t lineno, err, reason, file_len, cause_len;
    char     file[28];
    char     cause[36];              /* rst_why's 6th argument (Phase 3)     */
};

/* Which of the four RST_WHY* functions produced this record. `hook` stays "reset"
 * for all of them so a consumer keying on it does not break; this is the additive
 * detail. Knowing the function matters because they differ in ARGUMENT SHAPE --- the
 * preserve pair has no `reason` --- and because a site's macro is otherwise only
 * discoverable by reading TMM's source. */
static const char *
rst_fn_name(uint32_t id)
{
    switch (id) {
    case LS_TP_HOOK_RST:        return "rst_why";
    case LS_TP_HOOK_RST_VA:     return "rst_why_va";
    case LS_TP_HOOK_RST_PRE:    return "rst_why_preserve";
    case LS_TP_HOOK_RST_PRE_VA: return "rst_why_preserve_va";
    default:                    return "?";
    }
}

static void
emit_rst(const struct ls_rec *h, const struct rst_rec *r)
{
    uint32_t fn = r->file_len  < sizeof r->file  ? r->file_len  : (uint32_t)sizeof r->file;
    uint32_t cn = r->cause_len < sizeof r->cause ? r->cause_len : (uint32_t)sizeof r->cause;

    printf("{\"ts_ns\":%llu,\"seq\":%llu,\"slot\":%u,\"hook\":\"reset\","
           "\"fn\":\"%s\",\"schema\":%u,\"file\":\"",
           (unsigned long long)h->ts_ns, (unsigned long long)h->seq, h->slot,
           rst_fn_name(h->hook_id), h->schema_id);
    ls_json_str(r->file, fn);
    printf("\",\"line\":%u,\"err\":%u,\"reason\":%u,",
           r->lineno, r->err, r->reason);
    /* The cookie as ONE hex string, reassembled from the two halves. Hex rather than
     * decimal because it is an opaque identifier to be compared, never arithmetic on,
     * and "flow":"0" reads clearly as "no flow" --- which is a legitimate case, not a
     * missing field. */
    printf("\"flow\":\"%08x%08x\",\"cause\":\"",
           r->cookie_hi, r->cookie_lo);
    ls_json_str(r->cause, cn);
    printf("\"}\n");
}

/* SIZES PINNED HERE TOO. Each of these layouts is defined in THREE places --- the host
 * builder's header, the program's mirror, and this file --- because the drain is a
 * separate process sharing only bytes. Nothing compared the third against the other two.
 * A drain struct one byte off decodes every field past the divergence from the wrong
 * offset and prints plausible values, which is worse than refusing.
 *
 * These asserts are cheap and they are the only thing standing between a header edit and
 * a consumer that silently misreads the feed. */
_Static_assert(sizeof(struct rst_rec) == 92, "rst_rec must match struct ls_ctx_rst (92)");
_Static_assert(sizeof(struct http_rec) == 44, "http_rec must match the 44-byte HTTP record");

/* struct ls_ctx_sslerr --- substrate/ls_ctx_sslerr.h. WHY the TLS handshake or record
 * layer failed, from the site inside TMM that decided it. 96 bytes: AT PREVAIL's ctx
 * ceiling rather than under it, so this layout cannot grow. */
struct sslerr_rec {
    uint32_t cookie_lo, cookie_hi;   /* same cookie the reset record carries */
    uint32_t lineno, alert, func_len, msg_len;
    char     func[32];               /* __func__ --- ssl_err passes no __FILE__ */
    char     msg[40];                /* the first vararg                        */
};

/* The TLS AlertDescription, named. Rendering it matters more than it looks: the alert is
 * the ONE part of this a client can also see, so naming it is what lets someone line up
 * "my browser said handshake_failure" with the site inside TMM that sent it. Numbers are
 * the wire values from RFC 8446 §6.2 and its predecessors. */
_Static_assert(sizeof(struct sslerr_rec) == 96,
               "sslerr_rec must match struct ls_ctx_sslerr (96, AT PREVAIL's ceiling)");

static const char *
ssl_alert_name(uint32_t a)
{
    switch (a) {
    case 0:   return "close_notify";
    case 10:  return "unexpected_message";
    case 20:  return "bad_record_mac";
    case 22:  return "record_overflow";
    case 40:  return "handshake_failure";
    case 42:  return "bad_certificate";
    case 43:  return "unsupported_certificate";
    case 46:  return "certificate_unknown";
    case 47:  return "illegal_parameter";
    case 48:  return "unknown_ca";
    case 50:  return "decode_error";
    case 51:  return "decrypt_error";
    case 70:  return "protocol_version";
    case 80:  return "internal_error";
    case 112: return "unrecognized_name";
    /* Not a fallback to a plausible name: an alert we do not know is reported as its
     * number, so a reader sees an unfamiliar value rather than a wrong label. */
    default:  return "";
    }
}

static void
emit_sslerr(const struct ls_rec *h, const struct sslerr_rec *r)
{
    uint32_t fn = r->func_len < sizeof r->func ? r->func_len : (uint32_t)sizeof r->func;
    uint32_t mn = r->msg_len  < sizeof r->msg  ? r->msg_len  : (uint32_t)sizeof r->msg;
    const char *an = ssl_alert_name(r->alert);

    /* `fn` here is __func__, so it names the FUNCTION rather than the file --- the
     * opposite way round from the reset record, which has __FILE__ and no function. Both
     * fields are emitted under the names that say which is which: "func" not "file". */
    printf("{\"ts_ns\":%llu,\"seq\":%llu,\"slot\":%u,\"hook\":\"sslerr\","
           "\"schema\":%u,\"func\":\"",
           (unsigned long long)h->ts_ns, (unsigned long long)h->seq, h->slot,
           h->schema_id);
    ls_json_str(r->func, fn);
    printf("\",\"line\":%u,\"alert\":%u,\"alert_name\":\"%s\",",
           r->lineno, r->alert, an);
    /* TRUNCATION REPORTED, not hidden. func_len or msg_len at MAX-1 means the string was
     * cut --- 4.4% of function names and 11.2% of messages across the 475 sites. A
     * consumer diffing records needs to know it is comparing a prefix. */
    printf("\"truncated\":%s,",
           (fn == sizeof r->func - 1 || mn == sizeof r->msg - 1) ? "true" : "false");
    /* The SAME cookie the reset record carries for this connection, so the two feeds
     * join on it: "TLS failed here, then the connection was reset there". */
    printf("\"flow\":\"%08x%08x\",\"msg\":\"", r->cookie_hi, r->cookie_lo);
    ls_json_str(r->msg, mn);
    printf("\"}\n");
}

/* struct ls_ctx_h2abort --- substrate/ls_ctx_h2abort.h. WHY an HTTP/2 stream was aborted.
 * 48 bytes. The reason is a literal from http2.c and reaches no log, no iRule event and no
 * trace in a production build --- the only one of the four hooks for which that is true. */
struct h2abort_rec {
    uint32_t stream_id;      /* folded from the stream pointer --- identity, not address */
    uint32_t error;          /* enum http2_error                                        */
    uint32_t why_len;
    char     why[36];
};
_Static_assert(sizeof(struct h2abort_rec) == 48,
               "h2abort_rec must match struct ls_ctx_h2abort (48)");

static void
emit_h2abort(const struct ls_rec *h, const struct h2abort_rec *r)
{
    uint32_t wn = r->why_len < sizeof r->why ? r->why_len : (uint32_t)sizeof r->why;

    /* No file, no line, no alert, no flow --- and the field names say so rather than
     * borrowing the reset record's vocabulary for different data. `why` IS the site here:
     * 23 distinct literals over 36 call sites identify the decision more directly than a
     * line number would. */
    printf("{\"ts_ns\":%llu,\"seq\":%llu,\"slot\":%u,\"hook\":\"h2abort\","
           "\"schema\":%u,\"stream\":\"%08x\",\"error\":%u,\"truncated\":%s,\"why\":\"",
           (unsigned long long)h->ts_ns, (unsigned long long)h->seq, h->slot,
           h->schema_id, r->stream_id, r->error,
           (wn == sizeof r->why - 1) ? "true" : "false");
    ls_json_str(r->why, wn);
    printf("\"}\n");
}

/*
 * A record a PROGRAM published via bpf_ringbuf_output, not one a hook produced.
 *
 * REPORTED AS LENGTH AND HEX, deliberately. The bytes are whatever the program chose; the
 * host validated the length and nothing else. Naming fields here would put this agent's
 * authority behind a layout nobody checked --- which is exactly the mistake that had a
 * 92-byte reset record labelled HTTP. Interpreting these is a contract between the
 * program's author and their own consumer.
 */
static void
emit_prog(const struct ls_rec *h, const unsigned char *p, int n)
{
    int i;
    printf("{\"ts_ns\":%llu,\"seq\":%llu,\"slot\":%u,\"hook\":\"prog\","
           "\"schema\":%u,\"len\":%d,\"data\":\"",
           (unsigned long long)h->ts_ns, (unsigned long long)h->seq, h->slot,
           h->schema_id, n);
    for (i = 0; i < n; i++)
        printf("%02x", p[i]);
    printf("\"}\n");
}

static const char *
hook_name(uint32_t id)
{
    switch (id) {
    case LS_TP_HOOK_HTTP1_HDRS: return "http1";
    case LS_TP_HOOK_HTTP2_HDRS: return "http2";
    case LS_TP_HOOK_HTTP3_HDRS: return "http3";
    case LS_TP_HOOK_RST:
    case LS_TP_HOOK_RST_VA:
    case LS_TP_HOOK_RST_PRE:
    case LS_TP_HOOK_RST_PRE_VA: return "reset";
    case LS_TP_HOOK_SSLERR:     return "sslerr";
    case LS_TP_HOOK_H2ABORT:    return "h2abort";
    case LS_TP_HOOK_PROG:       return "prog";
    default:                    return "?";
    }
}

static void
emit_http(const struct ls_rec *h, const struct http_rec *r)
{
    printf("{\"ts_ns\":%llu,\"seq\":%llu,\"slot\":%u,\"hook\":\"%s\",\"schema\":%u,"
           "\"class\":\"%s\",\"parse_err\":%u,\"err\":%u,"
           "\"reject_reason\":%u,\"passthru\":%u,"
           "\"version\":\"%s\",\"method\":%u,\"header_count\":%u,"
           "\"status_code\":%u,\"invalid_flags\":%u,\"body_pos\":%u,"
           "\"hdr_bytes\":%u}\n",
           (unsigned long long)h->ts_ns, (unsigned long long)h->seq, h->slot,
           hook_name(h->hook_id), h->schema_id,
           klass(r), r->parse_err, r->err, r->reject_reason, r->passthru,
           VERSION_NAME[r->version & 3], r->method, r->header_count,
           r->status_code, r->invalid_flags, r->body_pos, r->hdr_bytes);
}

/* struct ls_tp_shield_ev --- substrate/ls_tp_shield.h. The enforcement-evidence
 * record: which shield selected SAFE_RETURN, in which mode, and the flat context
 * it saw. For the dtls_tx shield arg[3] = sz, the message size --- an oversized
 * sz beside a SAFE_RETURN is the fragment that would have overflowed the stack. */
struct shield_rec {
    unsigned int       mode;
    unsigned int       gen;
    unsigned int       verdict;
    unsigned int       ctx_len;
    unsigned long long arg[5];
};
_Static_assert(sizeof(struct shield_rec) == 56,
               "shield_rec must match struct ls_tp_shield_ev (56)");

static const char *
shield_mode_name(unsigned int m)
{
    switch (m) {
    case 1:  return "monitor";   /* WOULD have blocked --- body still ran */
    case 2:  return "enforce";   /* blocked --- body skipped, safe value returned */
    default: return "?";
    }
}

static void
emit_shield(const struct ls_rec *h, const struct shield_rec *r)
{
    /* `sz` is surfaced by name because it is the evidence; the full arg vector
     * follows for anyone who wants the rest of the context the shield saw. */
    printf("{\"ts_ns\":%llu,\"seq\":%llu,\"slot\":%u,\"hook\":\"shield\","
           "\"schema\":%u,\"mode\":\"%s\",\"gen\":%u,\"verdict\":%u,"
           "\"ctx_len\":%u,\"sz\":%llu,"
           "\"arg\":[%llu,%llu,%llu,%llu,%llu]}\n",
           (unsigned long long)h->ts_ns, (unsigned long long)h->seq, h->slot,
           h->schema_id, shield_mode_name(r->mode), r->gen, r->verdict,
           r->ctx_len, (unsigned long long)r->arg[3],
           (unsigned long long)r->arg[0], (unsigned long long)r->arg[1],
           (unsigned long long)r->arg[2], (unsigned long long)r->arg[3],
           (unsigned long long)r->arg[4]);
}

static void
emit_raw(const struct ls_rec *h, const unsigned char *p, int n)
{
    int i;
    printf("{\"ts_ns\":%llu,\"seq\":%llu,\"slot\":%u,\"hook\":\"%s\",\"schema\":%u,\"raw\":\"",
           (unsigned long long)h->ts_ns, (unsigned long long)h->seq, h->slot,
           hook_name(h->hook_id), h->schema_id);
    for (i = 0; i < n; i++)
        printf("%02x", p[i]);
    printf("\"}\n");
}

int
main(int argc, char **argv)
{
    const char *path = NULL;
    long idle_us = 2000, max_idle_us = 200000;
    int once = 0, quiet_stats = 0;
    struct ls_tp_seg *seg;
    unsigned long long delivered = 0, last_drops = 0;
    long backoff;

    static struct option opts[] = {
        { "segment",  required_argument, 0, 's' },
        { "interval", required_argument, 0, 'i' },
        { "once",     no_argument,       0, '1' },
        { "no-stats", no_argument,       0, 'q' },
        { "help",     no_argument,       0, 'h' },
        { 0, 0, 0, 0 }
    };
    int c;
    while ((c = getopt_long(argc, argv, "s:i:1qh", opts, NULL)) != -1) {
        switch (c) {
        case 's': path = optarg; break;
        case 'i': idle_us = atol(optarg); break;
        case '1': once = 1; break;
        case 'q': quiet_stats = 1; break;
        default:
            fprintf(stderr,
                "usage: %s --segment PATH [--interval US] [--once] [--no-stats]\n"
                "\n"
                "Consumes tracepoint records from the shared segment and writes\n"
                "JSON lines to stdout. Pipe them anywhere:\n"
                "\n"
                "  %s -s /dev/shm/ls_tp_ring | <publisher>   (BNK runs RabbitMQ, not NATS)\n"
                "  %s -s /dev/shm/ls_tp_ring > records.jsonl\n"
                "\n"
                "TMM does not depend on this process. Killing it, stalling it, or\n"
                "never starting it costs counted drops and nothing else.\n",
                argv[0], argv[0], argv[0]);
            return 2;
        }
    }
    if (path == NULL) {
        fprintf(stderr, "*** --segment is required\n");
        return 2;
    }

    signal(SIGINT, on_signal);
    signal(SIGTERM, on_signal);
    signal(SIGPIPE, SIG_DFL);      /* downstream closed: die, do not spin */

    seg = ls_tp_seg_open(path, 0);
    if (seg == NULL) {
        fprintf(stderr,
            "*** cannot open %s as a tracepoint segment.\n"
            "    If the file is all zeros, this process mapped its OWN tmpfs\n"
            "    rather than a segment shared with TMM --- in Kubernetes that\n"
            "    means /dev/shm is not an emptyDir with medium: Memory in BOTH\n"
            "    containers. It looks exactly like 'no traffic'.\n", path);
        return 1;
    }
    fprintf(stderr, "ls_drain: %s mapped, %u rings x %u bytes\n",
            path, seg->n_rings, seg->ring_data_size);

    backoff = idle_us;
    while (!g_stop) {
        int found = 0;
        unsigned int i;
        unsigned long long drops = 0;

        for (i = 0; i < seg->n_rings; i++) {
            struct ls_ring *r = ls_tp_seg_ring(seg, i);
            struct ls_rec h;
            unsigned char buf[512];
            int n;

            drops += atomic_load_explicit(&r->drops, memory_order_relaxed);

            /* Drain this ring until empty. ls_ring_consume acknowledges by
             * advancing consumer_pos --- which is what separates a drain from a
             * reader. A STREAM ring that is read but never acknowledged fills,
             * and TMM starts counting drops that nothing caused. */
            while ((n = ls_ring_consume(r, &h, buf, sizeof buf)) >= 0) {
                /* DISPATCH ON SCHEMA, NOT HOOK ID. This read `h.hook_id ==
                 * LS_TP_HOOK_RST`, which is id 4 --- plain rst_why alone. The reset
                 * family has four ids (4,5,6,7) all sharing schema 3, so records from
                 * rst_why_va, rst_why_preserve and rst_why_preserve_va never matched and
                 * fell through to emit_raw as hex.
                 *
                 * That is the SECOND HALF of the 2026-08-17 bug, left undone. The
                 * producer was fixed then --- ls_tp_schema_for() stopped labelling three
                 * of the four as HTTP --- but the consumer kept keying on one id. So the
                 * pair still disagreed, just in the other direction, and it went unseen
                 * because only rst_why was armed in the runs afterwards.
                 *
                 * The separation is the fix: SCHEMA decides the LAYOUT (it is the version
                 * of the byte format), hook_id decides only the LABEL, which is what
                 * rst_fn_name already does. */
                if (h.schema_id == LS_TP_SCHEMA_RST && n == (int)sizeof(struct rst_rec))
                    emit_rst(&h, (const struct rst_rec *)buf);
                else if (h.schema_id == LS_TP_SCHEMA_HTTP && n == (int)sizeof(struct http_rec))
                    emit_http(&h, (const struct http_rec *)buf);
                /* The LENGTH is checked as well as the schema, for every shape. A schema
                 * saying "sslerr" over a payload of the wrong size is a producer bug, and
                 * decoding it anyway would print plausible fields read from the wrong
                 * offsets. Falling through to emit_raw makes it visible instead. */
                else if (h.schema_id == LS_TP_SCHEMA_SSLERR && n == (int)sizeof(struct sslerr_rec))
                    emit_sslerr(&h, (const struct sslerr_rec *)buf);
                else if (h.schema_id == LS_TP_SCHEMA_H2ABORT && n == (int)sizeof(struct h2abort_rec))
                    emit_h2abort(&h, (const struct h2abort_rec *)buf);
                /* Shield enforcement evidence --- length-checked like every typed
                 * schema, so a 56-byte claim over the wrong size falls to raw. */
                else if (h.schema_id == LS_TP_SCHEMA_SHIELD && n == (int)sizeof(struct shield_rec))
                    emit_shield(&h, (const struct shield_rec *)buf);
                /* Program-emitted: NO length check against a struct, because there is no
                 * struct. Any length the producer accepted is valid here by construction. */
                else if (h.schema_id == LS_TP_SCHEMA_PROG)
                    emit_prog(&h, buf, n);
                else
                    emit_raw(&h, buf, n);
                delivered++;
                found = 1;
                if (g_stop)
                    break;
            }
        }

        /* The cursor has already advanced. This flush neither reverses that
         * acknowledgement nor establishes durable downstream acceptance. */
        fflush(stdout);

        if (!quiet_stats && drops != last_drops) {
            fprintf(stderr, "ls_drain: drops now %llu (+%llu) --- ring filled; "
                            "TMM never waited\n",
                    drops, drops - last_drops);
            last_drops = drops;
        }

        if (once)
            break;

        /* Adaptive backoff: spin close while records flow, ease off when idle.
         * There is no eventfd in the ring, so this polls. */
        if (found) {
            backoff = idle_us;
        } else {
            struct timespec ts = { backoff / 1000000, (backoff % 1000000) * 1000 };
            nanosleep(&ts, NULL);
            backoff = backoff * 2 > max_idle_us ? max_idle_us : backoff * 2;
        }
    }

    fflush(stdout);
    fprintf(stderr, "ls_drain: exit, %llu record(s) delivered, %llu drop(s) seen\n",
            delivered, last_drops);
    return 0;
}

substrate/drain/check_drain.c.text:
/* Can any behaviour of the drain agent affect the producer? It must not.
 *
 * This is the check for the governing constraint: TMM MUST NOT DEPEND ON AN
 * EXTERNAL CLIENT. Not on it running, not on it keeping up, not on it exiting
 * cleanly, not on it behaving. The claim is easy to assert in a comment and
 * worth very little there, so this drives a producer through four consumer
 * behaviours and measures what the producer actually experienced.
 *
 * The scenarios are the ones that will happen in production:
 *
 *   ABSENT     no consumer ever runs (sidecar not deployed, or crashed at boot)
 *   CRASHED    consumer dies mid-drain and never returns
 *   STALLED    consumer is alive but stops consuming (broker down, blocked write)
 *   HEALTHY    consumer keeps up
 *
 * In every one, the producer must: never block, never fail in any way other
 * than a counted drop, and never emit a corrupt record. The measurement that
 * carries the claim is MAX SINGLE-EMIT LATENCY --- if a stalled consumer could
 * back-pressure the producer, it would show up there and nowhere else. A pass
 * on record counts alone would not prove it.
 *
 * Plus the case that is a genuine trust boundary rather than a failure mode: a
 * consumer that writes a NONSENSE consumer_pos. It maps the segment read-write
 * because acknowledging requires it, so this is reachable by a buggy or hostile
 * agent. The requirement is that it can silence its own feed and nothing more
 * --- no crash, no corruption, no stall in the producer.
 */
#define _GNU_SOURCE
#include <assert.h>
#include <pthread.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

#include "../ls_tp_ring.h"

#define REC_BYTES 40u
#define EMITS     20000

enum consumer { ABSENT, CRASHED, STALLED, HEALTHY };

static struct ls_tp_seg *g_seg;
static volatile int      g_go, g_consumer_stop;

static uint64_t
now_ns(void)
{
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (uint64_t)ts.tv_sec * 1000000000ull + (uint64_t)ts.tv_nsec;
}

/* Stands in for the drain agent. CRASHED consumes briefly then abandons the
 * ring mid-stream, exactly as a killed sidecar would --- consumer_pos left
 * wherever it happened to be. */
static void *
consumer_thread(void *arg)
{
    enum consumer mode = (enum consumer)(intptr_t)arg;
    struct ls_ring *r = ls_tp_seg_ring(g_seg, 0);
    struct ls_rec h;
    unsigned char buf[256];
    int drained = 0;

    while (!g_go) { }

    for (;;) {
        if (g_consumer_stop)
            return NULL;
        if (mode == CRASHED && drained >= 50)
            return NULL;                       /* die mid-drain, never come back */
        if (mode == STALLED && drained >= 50) {
            usleep(1000);                      /* alive, consuming nothing */
            continue;
        }
        if (ls_ring_consume(r, &h, buf, sizeof buf) >= 0)
            drained++;
        else
            usleep(50);
    }
}

/* Returns max single-emit latency in ns. Any consumer-induced back-pressure
 * would appear here. */
static uint64_t
run(enum consumer mode, unsigned long long *landed, unsigned long long *dropped)
{
    struct ls_ring *r;
    pthread_t th;
    unsigned int rec[REC_BYTES / 4];
    uint64_t worst = 0;
    int i;

    ls_ring_init(ls_tp_seg_ring(g_seg, 0), LS_TP_RING_BYTES, LS_RING_STREAM);
    r = ls_tp_seg_ring(g_seg, 0);
    g_go = 0; g_consumer_stop = 0;

    if (mode != ABSENT)
        assert(pthread_create(&th, NULL, consumer_thread, (void *)(intptr_t)mode) == 0);

    *landed = *dropped = 0;
    g_go = 1;

    for (i = 0; i < EMITS; i++) {
        struct ls_rec h = { LS_TP_HOOK_HTTP1_HDRS, LS_TP_SCHEMA_HTTP,
                            (uint64_t)i, 1, REC_BYTES, 0 };
        uint64_t t0, dt;
        memset(rec, 0, sizeof rec);
        rec[0] = (unsigned int)i;

        t0 = now_ns();
        if (ls_ring_emit(r, &h, rec, REC_BYTES))
            (*landed)++;
        else
            (*dropped)++;
        dt = now_ns() - t0;
        if (dt > worst)
            worst = dt;
    }

    g_consumer_stop = 1;
    if (mode != ABSENT)
        pthread_join(th, NULL);

    assert(*landed + *dropped == EMITS);
    assert(atomic_load(&r->drops) == *dropped);
    return worst;
}

int
main(void)
{
    static const char *NAME[] = { "ABSENT", "CRASHED", "STALLED", "HEALTHY" };
    char path[] = "/tmp/.ls_drain_check";
    unsigned long long landed, dropped;
    uint64_t worst[4];
    int n = 0, m;

    unlink(path);
    g_seg = ls_tp_seg_open(path, 1);
    assert(g_seg != NULL);                                                  n++;

    printf("  producer emits %d records against each consumer behaviour\n", EMITS);
    for (m = ABSENT; m <= HEALTHY; m++) {
        worst[m] = run((enum consumer)m, &landed, &dropped);
        printf("    %-8s landed=%-6llu dropped=%-6llu max-emit=%llu ns\n",
               NAME[m], landed, dropped, (unsigned long long)worst[m]);

        /* 1. The producer always completed every emit. No blocking path exists,
         *    so this holds even with nothing consuming. */
        assert(landed + dropped == EMITS);                                  n++;

        /* 2. Loss is always COUNTED. A silent gap is indistinguishable from no
         *    traffic, which is the failure mode that makes a feed untrustworthy. */
        assert(atomic_load(&ls_tp_seg_ring(g_seg, 0)->drops) == dropped);   n++;

        /* 3. NO EMIT EVER BLOCKED. 20ms is enormous for a memcpy and two stores;
         *    real back-pressure would be orders beyond it. This is the assertion
         *    that actually carries the claim. */
        assert(worst[m] < 20000000ull);                                     n++;
    }

    /* 4. Absent, crashed and stalled consumers must all still let records land.
     *    A ring that wedged would show landed == 0. */
    assert(worst[ABSENT] < 20000000ull && worst[CRASHED] < 20000000ull &&
           worst[STALLED] < 20000000ull);                                   n++;

    /* 5. A HEALTHY consumer should keep the ring open --- this is the only mode
     *    where zero drops is achievable, and if it is not, the drain is not
     *    acknowledging and the "reader vs drain" distinction has been lost. */
    run(HEALTHY, &landed, &dropped);
    assert(landed > 0);                                                     n++;

    /* 6. THE TRUST BOUNDARY. A consumer maps this read-write because
     *    acknowledging requires it, so it can write nonsense. Requirement: it
     *    silences its own feed and does NOTHING else. Not a crash, not
     *    corruption, not a stall. */
    {
        struct ls_ring *r = ls_tp_seg_ring(g_seg, 0);
        unsigned int rec[REC_BYTES / 4];
        struct ls_rec h = { LS_TP_HOOK_HTTP1_HDRS, LS_TP_SCHEMA_HTTP, 0, 1, REC_BYTES, 0 };
        uint64_t t0, dt;
        int k, ok = 0;

        ls_ring_init(r, LS_TP_RING_BYTES, LS_RING_STREAM);
        memset(rec, 0, sizeof rec);
        /* consumer_pos far AHEAD of producer_pos: `prod - cons` underflows */
        atomic_store(&r->consumer_pos, (uint64_t)1 << 60);

        t0 = now_ns();
        for (k = 0; k < 1000; k++)
            ok += ls_ring_emit(r, &h, rec, REC_BYTES);
        dt = now_ns() - t0;

        printf("    HOSTILE  consumer_pos=2^60 -> landed=%d in %llu ns "
               "(degrades to drop-and-count)\n", ok, (unsigned long long)dt);
        assert(dt < 20000000ull);        /* did not stall */                n++;
        assert(ok + (int)atomic_load(&r->drops) == 1000);                   n++;
    }

    unlink(path);
    printf("ok    ls_drain  (%d assertions: producer unblocked and loss counted "
           "with consumer ABSENT/CRASHED/STALLED/HEALTHY, and hostile ack)\n", n);
    return 0;
}

substrate/drain/check_stream_source.c.text:
/* Controlled native source for reader handoff and failure tests. No TMM code. */
#include <inttypes.h>
#include <stdlib.h>
#include "../ls_tp_ring.h"

int main(int argc, char **argv)
{
    if (argc != 2) return 2;
    struct ls_tp_seg *s = ls_tp_seg_open(argv[1], 1);
    if (!s) return 3;
    struct ls_ring *r = ls_tp_my_ring(s);
    uint64_t sequence = 0;
    char command[4096] = {0};
    printf("{\"ready\":true}\n");
    fflush(stdout);
    while (fgets(command, sizeof command, stdin)) {
        unsigned count = 0;
        char hex[1025] = {0};
        unsigned emitted = 0;
        int consumed = -1;
        if (sscanf(command, "emit %u %1024s", &count, hex) == 2) {
            unsigned len = (unsigned)strlen(hex) / 2;
            unsigned char data[512] = {0};
            if (count > 100000 || strlen(hex) != 2 * len) return 4;
            for (unsigned i = 0; i < len; i++) {
                unsigned byte = 0;
                if (sscanf(hex + 2 * i, "%2x", &byte) != 1) return 5;
                data[i] = (unsigned char)byte;
            }
            for (unsigned i = 0; i < count; i++) {
                struct ls_rec rec = {.hook_id = 100, .schema_id = 100,
                    .seq = ++sequence, .slot = 7, .len = len, .ts_ns = sequence};
                emitted += ls_ring_emit(r, &rec, data, len);
            }
        } else if (!strcmp(command, "consume\n")) {
            struct ls_rec rec = {0};
            unsigned char data[512] = {0};
            consumed = ls_ring_consume(r, &rec, data, sizeof data);
            /* No payload output or downstream acceptance before this status. */
        } else if (!strcmp(command, "corrupt\n")) {
            s->version = 99;
        } else if (!strcmp(command, "misalign\n")) {
            atomic_store(&r->consumer_pos, 1);
        } else if (!strcmp(command, "quit\n")) {
            break;
        } else if (strcmp(command, "status\n")) {
            return 6;
        }
        printf("{\"producer\":\"%" PRIu64 "\",\"consumer\":\"%" PRIu64
               "\",\"drops\":\"%" PRIu64 "\",\"emitted\":%u,\"consumed\":%d}\n",
               atomic_load(&r->producer_pos), atomic_load(&r->consumer_pos),
               atomic_load(&r->drops), emitted, consumed);
        fflush(stdout);
    }
    munmap(s, LS_TP_SEG_SZ);
    return 0;
}

substrate/drain/ls_stream.c.text:
/* Separate-process STREAM reader: no cursor advance before downstream ACK.
 * The peer must durably journal a frame before acknowledging it. No TMM code
 * uses this executable. Legacy ls_drain must not share its segment.
 */
#define _GNU_SOURCE
#include <errno.h>
#include <inttypes.h>
#include <signal.h>
#include <stdlib.h>
#include <sys/file.h>
#include <sys/stat.h>
#include <sys/prctl.h>
#include <sys/sysmacros.h>
#include <time.h>
#include "../ls_tp_ring.h"

static const char *segment_path;
static pid_t producer;
static uint64_t expected_start;
static struct stat segment_stat, exe_stat;
static volatile sig_atomic_t stopped;
static void stop(int sig) { (void)sig; stopped = 1; }
static void fail(const char *message) { fprintf(stderr, "ls_stream: %s\n", message); exit(1); }

static uint64_t start_time(pid_t pid)
{
    char path[64], buf[4096], *save, *p;
    snprintf(path, sizeof path, "/proc/%ld/stat", (long)pid);
    FILE *f = fopen(path, "r");
    if (!f) return 0;
    p = fgets(buf, sizeof buf, f);
    fclose(f);
    if (!p || !(p = strrchr(buf, ')'))) return 0;
    p = strtok_r(p + 1, " ", &save);
    for (int field = 3; p && field < 22; field++) p = strtok_r(NULL, " ", &save);
    return p ? strtoull(p, NULL, 10) : 0;
}

static void same_source(void)
{
    struct stat s, e;
    char path[64];
    snprintf(path, sizeof path, "/proc/%ld/exe", (long)producer);
    if (start_time(producer) != expected_start || stat(path, &e) ||
            e.st_dev != exe_stat.st_dev || e.st_ino != exe_stat.st_ino ||
            stat(segment_path, &s) || s.st_dev != segment_stat.st_dev ||
            s.st_ino != segment_stat.st_ino || s.st_size != segment_stat.st_size)
        fail("source identity changed; no acknowledgement");
}

/* A live PID alone is not evidence that it owns the supplied segment. Require
 * a shared writable mapping of this inode in the pinned producer process. */
static void mapped_source(void)
{
    char path[64], line[4096], perms[5];
    unsigned long low, high;
    unsigned major_id, minor_id;
    unsigned long long offset, inode;
    int found = 0;
    snprintf(path, sizeof path, "/proc/%ld/maps", (long)producer);
    FILE *f = fopen(path, "r");
    if (!f) fail("producer mappings unavailable");
    while (fgets(line, sizeof line, f)) {
        if (sscanf(line, "%lx-%lx %4s %llx %x:%x %llu", &low, &high,
                   perms, &offset, &major_id, &minor_id, &inode) == 7 &&
                !strcmp(perms, "rw-s") && !offset &&
                high - low >= LS_TP_SEG_SZ && inode == segment_stat.st_ino &&
                major_id == major(segment_stat.st_dev) &&
                minor_id == minor(segment_stat.st_dev)) found = 1;
    }
    fclose(f);
    if (!found) fail("producer does not map this segment");
}

static void acknowledge(const char *token)
{
    char line[128], expected[128];
    if (fflush(stdout) || ferror(stdout)) fail("output failed before ACK");
    snprintf(expected, sizeof expected, "ACK %s\n", token);
    if (!fgets(line, sizeof line, stdin) || strcmp(line, expected))
        fail("missing or invalid ACK; cursor retained");
    same_source();
    mapped_source();
}

int main(int argc, char **argv)
{
    if (argc < 4 || argc > 5 || (argc == 5 && strcmp(argv[4], "--once"))) {
        fprintf(stderr, "usage: ls_stream SEGMENT PRODUCER_PID START_TICKS [--once]\n");
        return 2;
    }
    pid_t parent = getppid();
    if (parent == 1 || prctl(PR_SET_PDEATHSIG, SIGKILL) || getppid() != parent)
        fail("collector parent unavailable");
    segment_path = argv[1];
    producer = (pid_t)strtol(argv[2], NULL, 10);
    expected_start = strtoull(argv[3], NULL, 10);
    if (producer <= 0 || !expected_start || start_time(producer) != expected_start)
        fail("producer identity mismatch");
    char path[64], boot[64];
    struct stat ns;
    snprintf(path, sizeof path, "/proc/%ld/exe", (long)producer);
    if (stat(path, &exe_stat) || stat("/proc/self/ns/pid", &ns)) fail("source stat failed");
    FILE *f = fopen("/proc/sys/kernel/random/boot_id", "r");
    if (!f || fscanf(f, "%63s", boot) != 1) fail("boot identity unavailable");
    fclose(f);
    if (strspn(boot, "0123456789abcdef-") != strlen(boot)) fail("invalid boot identity");
    int fd = open(segment_path, O_RDWR | O_CLOEXEC);
    if (fd < 0 || fstat(fd, &segment_stat) || !S_ISREG(segment_stat.st_mode) ||
            segment_stat.st_size != (off_t)LS_TP_SEG_SZ) fail("invalid segment file");
    if (flock(fd, LOCK_EX | LOCK_NB)) fail("another cooperative reader owns this segment");
    struct ls_tp_seg *s = mmap(NULL, LS_TP_SEG_SZ, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (s == MAP_FAILED) fail("cannot map segment");
    if (s->magic != LS_TP_SEG_MAGIC || s->version != LS_TP_SEG_VERSION ||
            s->n_rings != LS_TP_MAX_RINGS || s->ring_stride != LS_TP_STRIDE ||
            s->ring_data_size != LS_TP_RING_BYTES) fail("invalid segment geometry");
    struct sigaction action = {0};
    action.sa_handler = stop;
    sigemptyset(&action.sa_mask);
    if (sigaction(SIGTERM, &action, NULL) || sigaction(SIGINT, &action, NULL))
        fail("cannot install stop handler");
    same_source();
    mapped_source();
    printf("{\"kind\":\"source\",\"token\":\"H\",\"boot\":\"%s\","
           "\"pid_namespace\":\"%ju\",\"pid\":\"%ld\",\"start\":\"%" PRIu64 "\","
           "\"segment_device\":\"%ju\",\"segment_inode\":\"%ju\","
           "\"exe_device\":\"%ju\",\"exe_inode\":\"%ju\",\"segment_version\":%u}\n",
           boot, (uintmax_t)ns.st_ino, (long)producer, expected_start,
           (uintmax_t)segment_stat.st_dev, (uintmax_t)segment_stat.st_ino,
           (uintmax_t)exe_stat.st_dev, (uintmax_t)exe_stat.st_ino, s->version);
    acknowledge("H");
    uint64_t last_drops[LS_TP_MAX_RINGS];
    for (unsigned i = 0; i < LS_TP_MAX_RINGS; i++) last_drops[i] = UINT64_MAX;
    do {
        int found = 0;
        same_source();
        unsigned claimed = atomic_load_explicit(&s->claimed, memory_order_acquire);
        if (claimed > s->n_rings) fail("ring claims exceed capacity");
        for (unsigned i = 0; i < claimed && !stopped; i++) {
            /* Use verified compile-time geometry even if the header changes. */
            struct ls_ring *r = (void *)((uint8_t *)s + sizeof *s + i * LS_TP_STRIDE);
            if (r->magic != LS_RING_MAGIC || r->version != 1 ||
                    r->policy != LS_RING_STREAM || r->data_size != LS_TP_RING_BYTES)
                fail("invalid ring geometry/policy");
            uint64_t drops = atomic_load_explicit(&r->drops, memory_order_relaxed);
            char token[96];
            if (drops != last_drops[i]) {
                snprintf(token, sizeof token, "D:%u:%" PRIu64, i, drops);
                printf("{\"kind\":\"ring_health\",\"token\":\"%s\",\"ring\":%u,"
                       "\"drops\":\"%" PRIu64 "\",\"drop_bytes\":\"%" PRIu64 "\"}\n",
                       token, i, drops, atomic_load_explicit(&r->drop_bytes, memory_order_relaxed));
                acknowledge(token);
                last_drops[i] = drops;
            }
            uint64_t cons = atomic_load_explicit(&r->consumer_pos, memory_order_acquire);
            uint64_t prod = atomic_load_explicit(&r->producer_pos, memory_order_acquire);
            if (cons > prod || prod - cons > r->data_size ||
                    (cons | prod) & (LS_RING_ALIGN - 1)) fail("invalid ring positions");
            if (cons == prod) continue;
            uint32_t off = cons & (r->data_size - 1);
            uint8_t *data = ls_ring_data(r) + off;
            uint32_t hdr = atomic_load_explicit((_Atomic uint32_t *)(void *)data, memory_order_acquire);
            if (hdr & LS_RING_BUSY) continue;
            uint32_t body = hdr & LS_RING_LEN_MASK;
            if (body > r->data_size - LS_RING_HDR_SZ) fail("invalid record length");
            uint32_t step = ls_ring_round(LS_RING_HDR_SZ + body);
            if (step > r->data_size - off || step > prod - cons) fail("record outside committed range");
            snprintf(token, sizeof token, "R:%u:%" PRIu64 ":%" PRIu64, i, cons, cons + step);
            printf("{\"kind\":\"%s\",\"token\":\"%s\",\"ring\":%u,"
                   "\"begin\":\"%" PRIu64 "\",\"end\":\"%" PRIu64 "\"",
                   hdr & LS_RING_DISCARD ? "discard" : "record", token, i, cons, cons + step);
            if (!(hdr & LS_RING_DISCARD)) {
                struct ls_rec rec;
                unsigned char payload[512];
                if (body < sizeof rec || body - sizeof rec > sizeof payload) fail("unsupported record size");
                memcpy(&rec, data + LS_RING_HDR_SZ, sizeof rec);
                if (rec.len != body - sizeof rec) fail("record/payload length mismatch");
                memcpy(payload, data + LS_RING_HDR_SZ + sizeof rec, rec.len);
                printf(",\"hook_id\":%u,\"schema\":%u,\"slot\":%u,\"seq\":\"%" PRIu64
                       "\",\"ts_ns\":\"%" PRIu64 "\",\"data\":\"",
                       rec.hook_id, rec.schema_id, rec.slot, rec.seq, rec.ts_ns);
                for (unsigned j = 0; j < rec.len; j++) printf("%02x", payload[j]);
                printf("\"");
            }
            printf("}\n");
            acknowledge(token);
            if (atomic_load_explicit(&r->consumer_pos, memory_order_acquire) != cons)
                fail("another consumer moved the cursor");
            atomic_store_explicit(&r->consumer_pos, cons + step, memory_order_release);
            found = 1;
        }
        if (argc == 5 && !found) break;
        if (!found) { struct timespec delay = {0, 2000000}; nanosleep(&delay, NULL); }
    } while (!stopped);
    munmap(s, LS_TP_SEG_SZ);
    close(fd);
    return 0;
}

